if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_application() {
    _argc_util_cache 3600 _helper_application
}

_choice_bundle_id() {
    _argc_util_cache 3600 _helper_bundle_id
}

_choice_env_var() {
    compgen -e
}

_choice_filenames() {
    _argc_util_comp_path
}

_choice_sdk() {
    command -v xcodebuild >/dev/null 2>&1 || return 0
    xcodebuild -showsdks 2>/dev/null | sed -n 's/^[[:space:]].*-sdk[[:space:]]*//p'
}

_helper_app_paths() {
    local dir
    for dir in /Applications /System/Applications "$HOME/Applications"; do
        [ -d "$dir" ] || continue
        find "$dir" -maxdepth 2 -name '*.app' -prune -print
    done
}

_helper_application() {
    local app
    _helper_app_paths | while IFS= read -r app; do
        app=${app##*/}
        printf '%s\n' "${app%.app}"
    done
}

_helper_bundle_id() {
    local app
    _helper_app_paths | while IFS= read -r app; do
        plutil -extract CFBundleIdentifier raw -o - "$app/Contents/Info.plist" 2>/dev/null
    done
}
